def choose_move(observation):
    x = observation.get("self_position", [0, 0])[0]
    y = observation.get("self_position", [0, 0])[1]

    grid_w = observation.get("grid_width", 0)
    grid_h = observation.get("grid_height", 0)

    dx = 0
    dy = 0

    resources = observation.get("resources", [])
    if resources:
        best = None
        best_dist = 10**9
        for r in resources:
            rx = r.get("x", x)
            ry = r.get("y", y)
            d = abs(rx - x) + abs(ry - y)
            if d < best_dist:
                best_dist = d
                best = (rx, ry)
        if best is not None:
            rx, ry = best
            if rx > x:
                dx = 1
            elif rx < x:
                dx = -1
            if ry > y:
                dy = 1
            elif ry < y:
                dy = -1
            return [dx, dy]

    obstacles = observation.get("obstacles", [])
    blocked = set((o.get("x", -1), o.get("y", -1)) for o in obstacles)

    nx = x + 0
    ny = y + 0
    if (nx + 1, ny) not in blocked:
        if nx + 1 < grid_w:
            dx = 1
            return [dx, dy]
    if (nx - 1, ny) not in blocked:
        if nx - 1 >= 0:
            dx = -1
            return [dx, dy]
    if (nx, ny + 1) not in blocked:
        if ny + 1 < grid_h:
            dy = 1
            return [dx, dy]
    if (nx, ny - 1) not in blocked:
        if ny - 1 >= 0:
            dy = -1
            return [dx, dy]

    return [0, 0]
